pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium gaps (10..=20) are partially usable but risky.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // If the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // Penalize if next item cannot fit in post residual (forced split).
    if next_item_size > post_residual && next_item_size > 0 {
        score += next_item_size as f64 * 0.3;
    }

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Pressure from many open bins: prefer filling existing bins.
    score += open_bins_count as f64 * 1.5;

    // Deviation from mean residual: prefer bins that are fuller than average.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate: baseline high cost, reduced late in stream
    // or when item is huge and fits nowhere well.
    if bin_residual == bin_capacity {
        score = 120.0
            - (step_index as f64 / total_items.max(1) as f64) * 20.0
            - (fitting_bins_count as f64) * 5.0;
        // Opening a new bin is reasonable if item is large and would leave
        // a small dead gap in any existing bin.
        if item_size > bin_capacity * 3 / 4 && post_residual == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A post_residual that is too small to ever hold a future item is pure waste.
    // Penalize small unusable gaps quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0; // dead space penalty
    }
    // If post_residual cannot fit the lookahead item, this bin's leftover is
    // likely stranded -> penalize, unless the gap is large enough to be useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
    }
    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score -= 6.0;
    }

    // --- Tightness reward relative to bin fill ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // --- Open bins pressure: with many open bins, prefer consolidation ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.9 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    // --- Last-chance bin: if this is the ONLY bin that fits, avoid opening new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are poor
        // for this item (item barely fits nowhere tightly) or late in stream
        // with many bins. Otherwise discourage.
        let worst_case = (mean_residual - item_size as f64).abs();
        score = 45.0 + 0.3 * open_bins_count as f64 - 0.2 * worst_case;
        if next_item_size > 0 && next_item_size >= item_size {
            // saving empty space for a bigger lookahead item can be smart
            score -= 10.0;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" fills
    // (small post_residual is good, but dead space in awkward classes is worse).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class reward: post_residual divisible by common item sizes (10, 20, 25, 50)
    // means future items can fill it exactly.
    let harmonic_bonus = if post_residual % 10 == 0 { 8.0 }
        else if post_residual % 20 == 0 { 6.0 }
        else if post_residual % 25 == 0 { 6.0 }
        else if post_residual % 5 == 0 { 3.0 }
        else { 0.0 };
    score -= harmonic_bonus;

    // Dead-space penalty: small awkward residuals (1..=9) are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Exact match with lookahead item: strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // lookahead fits: mild reward proportional to leftover after next item
            let after_next = post_residual - next_item_size;
            score -= 10.0 - (after_next as f64) * 0.1;
        } else {
            // lookahead won't fit here: penalize slightly more for tiny residuals
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 40.0;
        // Cheaper to open new bin when few bins open or item is large
        score -= (open_bins_count as f64) * 0.5;
        score -= (item_size as f64 / cap) * 20.0;
        // If no bin fits (this is the only fitting candidate), opening is natural
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Prefer tighter bins overall: deviation from mean residual
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Slight preference for compacting large items early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Dead-space penalty for small awkward leftovers (hard to reuse).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when fits are poor
    // or the current item would leave an unusable remainder.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5;
        let awkward = post_residual > 0 && post_residual < 10;
        if poor_fit || awkward {
            score -= 60.0;
        } else {
            score += 35.0;
        }
    }

    // Lookahead: if the next item would fit the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0;
            // Bonus when next item fits snugly too (chain of good fits).
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * next_fit;
        } else {
            // Next item won't fit here: mildly penalize wasting large residuals
            // that could have served the next item.
            if next_item_size as f64 > post_residual as f64
                && next_item_size as f64 <= bin_residual as f64
            {
                score += 6.0;
            }
        }
    }

    // Global state coupling: many open bins with high mean residual suggests
    // fragmentation; prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fragmentation = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * fragmentation * (1.0 - progress);
    }

    // Scale of open bins: with many open bins, discourage opening more.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but penalize very small post-residuals
    // that are "dead space" (unusable for typical future items).
    let small_item = 10u32.min(bin_capacity / 10).max(1);
    if post_residual > 0 && post_residual < small_item {
        score += 25.0; // dead space penalty
    }

    // Harmonic class logic: classify post_residual by capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Residuals in the "half bin" band are valuable (fit mid-size items).
    if frac >= 0.4 && frac <= 0.6 {
        score -= 12.0;
    } else if frac > 0.6 && frac <= 0.8 {
        score -= 6.0;
    } else if frac < 0.2 && post_residual > 0 {
        score += 8.0; // tiny slivers are wasteful
    }

    // Modulo classes on post_residual: residuals divisible by common
    // item sizes (10/20/25) are reusable "harmonic" pockets.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; leftover becomes dead weight
            score += 6.0;
        }
        // Harmonic pairing: post_residual % next_item_size == 0 means
        // multiple future items could tile the remaining space.
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current bins are crowded (mean residual low) or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / cap;
        // penalize new bin more when open bins have plenty of room
        score += 15.0 + 40.0 * crowding - 10.0 * (1.0 - progress);
    }

    // Mild preference to consolidate across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // are pure waste — penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward very tight fits (item nearly fills the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If this bin can host the next item too, chaining is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for the next item: dead space risk.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones rather than spreading items.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 6.0;

    // Prefer bins below the mean residual when many bins are open
    // (balances residual distribution, keeps more bins usable).
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // New empty bin candidate: only attractive when the item is huge
    // and no tight fit exists; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let big = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 20.0 * big;
    }

    score
}

