pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, smoothly warped by progress
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear penalty on dead space: small residuals are hard to fill
    score += 30.0 * (1.0 - norm_pr).powi(4) * norm_pr.powi(2) * (1.0 + progress);

    // Reward tight fits relative to bin size
    score -= 20.0 * (item_size as f64 / cap) * (1.0 - norm_pr).powi(2);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving space that fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * (open_bins_count as f64).sqrt() * norm_pr;

    // Deviation from mean residual: prefer bins near mean to keep options open
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual falls into
    // "coarse" classes (large gaps) are more reusable; fine slivers are dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class width: capacity divided into 10 harmonic bands (capacity fractions).
    let band = cap / 10.0;
    let post_class = (post / band).floor(); // 0..=10

    // Reward bins whose post_residual class matches a size the next item could use:
    // leftover space in class k is "harmonically compatible" if next item fits it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // leftover can host the next item: strong reward, scaled by tightness
            score -= 12.0 + 8.0 * (nxt / post.max(1.0));
        } else {
            // leftover cannot host next item: penalize proportional to waste
            score += 4.0 * (1.0 - nxt / cap);
        }
    }

    // Integer-division threshold on post_residual: leftovers below 10 are dead space
    // (min item size), heavily penalized via class-based surcharge.
    let dead = post_residual / 10; // integer division: 0 => unusable
    if dead == 0 && post_residual > 0 {
        score += 15.0;
    }

    // Reward leaving residuals that are exact capacity fractions (50, 33, 25, 20...)
    // since these align with modulo-friendly item classes.
    for &f in &[50u32, 33, 25, 20, 10] {
        if post_residual % f == 0 && post_residual > 0 {
            score -= 6.0;
            break;
        }
    }

    // Penalize bins already near-full only mildly; prefer tight fits overall
    // (post_residual term already does this). Add last-chance bonus: if this is
    // the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.1 * post;
    }

    // New-bin candidate: neutral-ish baseline so it wins only when all open bins
    // would create bad classes. Encourage opening fresh bins early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.9 - 10.0 * (1.0 - progress) + 5.0 * (post_class / 10.0);
        // if next item is large, a fresh bin is attractive
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (consume
    // fragmented space first), keeping large-residual bins flexible.
    score -= 0.05 * (mean_residual - post);

    // Mild penalty for spreading across too many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (or the lookahead item) are wasted capacity -> heavy penalty.
    if post_residual > 0 {
        let min_item = 1u32;
        let unusable = post_residual < min_item.max(next_item_size.min(post_residual));
        if unusable {
            score += 40.0 + 0.5 * post_residual as f64;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // creates a gap the next item cannot use
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 + 1.5 * open_bins_count as f64;
        // But if this bin's residual is far below mean residual, opening
        // a fresh bin may be better than fragmenting a large-residual bin.
        if bin_residual as f64 > mean_residual + 0.5 * bin_capacity as f64 {
            score -= 20.0;
        }
    } else {
        // Slight preference for bins with larger residuals (best-fit flavor).
        score -= 0.1 * bin_residual as f64 / bin_capacity as f64;
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (wasted space is the enemy).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits into the post residual,
    // this bin is doubly valuable (chains two items).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportional to how snugly the next item also fits.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 40.0 - chain_waste.min(40.0) * 0.5;
        } else {
            // Penalize dead space that the next item cannot use,
            // scaled by how much is stranded.
            let stranded = (post_residual - next_item_size.saturating_sub(1)) as f64;
            score += stranded * 0.3;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are precious.
    let tightness = mean_residual - bin_residual as f64;
    score += tightness * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless it would strand a lot of space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // (would leave unusable slivers in existing bins) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = (item_size as f64) / bin_capacity as f64;
        // Penalize opening new bins for small items; relax for big items late.
        score += 30.0 * (1.0 - large_item) + 20.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0; // fresh bin can chain the next item too
        }
    }

    // Mild pressure against proliferating many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward low post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual but unusable for next item.
    if next_item_size > 0 {
        if next_item_size > post_residual && post_residual > 0 {
            // Dead space: post_residual too small for the lookahead item.
            let waste = post_residual as f64;
            score += 12.0 * (waste / 10.0).min(5.0);
        } else if post_residual >= next_item_size {
            // Reward bins that can also host the lookahead item (chaining).
            score -= 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // open bins; penalize more when open bins are still fairly full (usable).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_usable = mean_residual / bin_capacity as f64;
        // Penalize new bins more when existing bins have large usable residuals
        // and few bins are open; relax late in the stream.
        score += 20.0 + 30.0 * avg_usable + 10.0 * (1.0 - progress) - (open_bins_count as f64).min(10.0);
    } else {
        // Mild preference for fuller bins (smaller residual) among open bins.
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Dynamic time horizon: early in stream, be conservative (avoid fragmenting);
    // late in stream, squeeze tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - fit_ratio);

    // Discourage leaving residuals in the awkward 1..=10 range (hard to fill).
    if post_residual >= 1 && post_residual <= 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits, scaled by smooth polynomial in post_residual
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Stream-progress coupling: later in stream, penalize waste more aggressively
    let p2 = progress * progress;
    score += progress * post * (0.3 + 0.7 * p2);

    // Dead-space penalty: residuals too small for typical items
    let dead = (1.0 - norm_post).min(1.0);
    score += 20.0 * dead * dead * (1.0 - norm_post);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 5.0 + 5.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 - post) / cap;
    }

    // Crowding: many open bins with high mean residual -> encourage consolidation
    let crowd = (open_bins_count as f64) / (1.0 + mean_residual / cap);
    score += 0.5 * crowd * (0.5 + p2);

    // New-bin candidate: mildly penalize opening new bins unless waste is large
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * progress + 0.2 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but penalize very small post-residuals
    // that are "dead space" (unusable for typical future items).
    let small_item = 10u32.min(bin_capacity / 10).max(1);
    if post_residual > 0 && post_residual < small_item {
        score += 25.0; // dead space penalty
    }

    // Harmonic class logic: classify post_residual by capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Residuals in the "half bin" band are valuable (fit mid-size items).
    if frac >= 0.4 && frac <= 0.6 {
        score -= 12.0;
    } else if frac > 0.6 && frac <= 0.8 {
        score -= 6.0;
    } else if frac < 0.2 && post_residual > 0 {
        score += 8.0; // tiny slivers are wasteful
    }

    // Modulo classes on post_residual: residuals divisible by common
    // item sizes (10/20/25) are reusable "harmonic" pockets.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; leftover becomes dead weight
            score += 6.0;
        }
        // Harmonic pairing: post_residual % next_item_size == 0 means
        // multiple future items could tile the remaining space.
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current bins are crowded (mean residual low) or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / cap;
        // penalize new bin more when open bins have plenty of room
        score += 15.0 + 40.0 * crowding - 10.0 * (1.0 - progress);
    }

    // Mild preference to consolidate across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are almost unusable
    // for future items (sizes >= 1, practically >= 10 in classic streams).
    let dead_zone_start = 1.0f64;
    let dead_zone_end = 12.0f64;
    if (post_residual as f64) >= dead_zone_start && (post_residual as f64) <= dead_zone_end {
        // Heavily penalize gaps that waste most of the bin's usable slack.
        score += 60.0 * (dead_zone_end - post_residual as f64 + 1.0);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual >= 13 {
        // Reward leaving a gap that can still host a meaningful item,
        // scaled by how close the gap is to a "typical" item size.
        score -= 10.0 * (1.0 - ((post_residual as f64) / bin_capacity as f64));
    }

    // Last-chance bin: strongly prefer filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferating bins when existing ones fit.
    score += 2.0 * open_bins_count as f64;

    // Prefer bins whose residual is close to the mean residual (balanced packing),
    // unless it's the fresh-bin candidate.
    if bin_residual != bin_capacity {
        score += 0.5 * ((bin_residual as f64 - mean_residual).abs());
    }

    // New-bin candidate: make it attractive only when the item barely fits
    // nowhere else or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        // Baseline: opening a new bin is moderately expensive.
        score = 45.0 + 3.0 * open_bins_count as f64;
        // If this bin is the last resort, opening is fine (score already competitive).
        // If lookahead item is small, a fresh bin keeps flexibility.
        if next_item_size > 0 && (next_item_size as f64) >= 0.6 * (bin_capacity as f64) {
            score -= 15.0; // large lookahead favors a fresh bin
        }
        if next_item_size > 0 && (next_item_size as f64) <= 0.15 * (bin_capacity as f64) {
            score += 20.0; // tiny lookahead: don't waste a fresh bin now
        }
    }

    // Slight stream-progression term: tighten packing as the stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect 2-step match — next item exactly fills the leftover space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward: next item fits into the remaining space (good lookahead chain).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra bonus when the leftover after both placements would be small.
        let two_step_left = post_residual - next_item_size;
        score -= (two_step_left as f64).min(20.0) * 0.8;
    }
    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize leaving residual far below mean residual (creating unusable slivers).
    let res_f = post_residual as f64;
    if res_f < mean_residual {
        score += (mean_residual - res_f) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Reward tight fits now (small post residual relative to item size).
    score -= (item_size as f64) * 0.1;

    // New-bin candidate: neutral-ish baseline; discourage unless open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Prefer new bin late in the stream less (keep bins consolidated early).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness: reward small post-residuals nonlinearly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that can never fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if next item fits in post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack / 10.0);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer filling existing ones over spreading
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 3.0 * pressure;

    // Time horizon: early in stream, allow new bins; late, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (balance consolidation)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening unless item is huge relative to residual
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += 12.0 + scarcity - 25.0 * fill_ratio * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * (1.0 - x) * (1.0 - 2.0 * x); // signed cubic shape
    let progress_coupling = poly * (progress - 0.5) * 60.0;

    // Base preference for tight fits, softly non-linear
    let mut score = pr + 8.0 * pr * pr / cap;

    // Penalize dead space that shrinks as stream progresses (be pickier later)
    score += 20.0 * x * x * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    }

    // Lookahead: reward if next item can use the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Deviation from mean residual: prefer bins near the mean (smooth)
    score += 0.05 * (pr - mean_residual).abs();

    // Mild new-bin penalty so open bins are preferred unless very poor fit
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * (1.0 - progress) * x;
    }

    score + progress_coupling
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead-space" classes (post_residual <= 10) are heavily rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit
    } else if pr <= 10 {
        score -= 30.0 - pr as f64; // near-perfect: tiny dead space
    } else {
        // modulo classes: leftover mod 10 indicates pairing potential with
        // typical small items (1..=10 range granularity)
        let m = pr % 10;
        if m == 0 {
            score -= 8.0; // class-aligned leftover, easy to fill later
        } else if m >= 7 {
            score -= 4.0;
        } else {
            score += (10 - m) as f64 * 0.8; // awkward leftover class
        }
    }

    // Integer-division thresholds on post_residual: which harmonic band it lands in
    let band = pr / 25; // 0..4
    match band {
        0 => score -= 5.0,
        1 => score -= 2.0,
        2 => score += 1.0,
        _ => score += 3.0,
    }

    // Lookahead coupling: if next item fits the post residual exactly or nearly,
    // reward strongly (chained packing).
    if next_item_size > 0 && next_item_size <= pr {
        let next_gap = pr - next_item_size;
        if next_gap <= 10 {
            score -= 20.0 - next_gap as f64;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > pr {
        // next item cannot use this leftover: penalize proportional to leftover size
        score += (pr as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer tight bins over loose ones when many bins are open
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Mild pressure toward consolidation as the stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // Penalize bins far from the mean residual (outlier dead space)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: only attractive when current leftovers are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.25 && fitting_bins_count <= 2 {
            score -= 12.0; // open fresh bin rather than wreck a small residual
        } else {
            score += 20.0; // prefer filling existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A post_residual in (0, 10) is a "dead gap" that can never fit a future item
    // (min item size 1..100, but small gaps waste capacity).
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - pr) / 10.0; // dead gap penalty
    }

    // Reward near-perfect fits (post_residual very small but usable).
    if post_residual <= 5 && post_residual > 0 {
        score -= 25.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good filler.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score -= 0.15 * (mean_residual - bin_res_f);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is large and post_residual is a tiny gap, penalize leaving it.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < next_item_size as u32 {
        score += 8.0;
    }

    // New-bin candidate (empty bin): neutral residual = capacity; make it moderately
    // attractive only when no good fit exists (its raw post_residual is high, so add
    // a mild discount so it competes with poor fits but loses to tight fits).
    if bin_residual == bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (chain packing).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - next).abs();
        if post >= next {
            if gap == 0.0 {
                score -= 500.0; // perfect two-item chain
            } else if gap <= 10.0 {
                score -= 150.0;
            } else {
                score -= 40.0 * (1.0 - gap / post.max(1.0));
            }
        } else {
            // Next item won't fit: penalize proportionally to the waste.
            score += 0.5 * (next - post);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize spreading across too many open bins early in the stream;
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score += 0.2 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mild penalty for using a fresh bin when open bins exist and fit is loose.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
        // But allow fresh bin if next item is huge and would strand residual.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual is good).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize small dead space: residual too small to ever be useful (< 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Next item cannot use the leftover space: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Prefer bins below mean residual (fill emptier bins first to keep
    // tight bins available for small items).
    score += (mean_residual - bin_residual as f64) * 0.10;

    // As the stream progresses, discourage opening new bins slightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus escalation with open bins and progress.
        score += 8.0 + open_bins_count as f64 * 1.5 + progress * 15.0;
    } else {
        // Existing bins get a mild bonus that grows with progress.
        score -= progress * 3.0;
    }

    // Slight penalty for very large residuals being consumed by small items.
    if (bin_residual as f64) > mean_residual * 1.5 && item_size < 30 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // Smooth non-linear core: penalize residual, reward tight fills superlinearly
    let mut score = pr * (1.0 + 0.8 * fill * fill);

    // Cubic coupling of fill with stream progress: early on tolerate waste,
    // later demand tight packing more aggressively
    score -= 30.0 * fill.powi(3) * (0.3 + 0.7 * progress);

    // Dead-space penalty: residual too small for any plausible item (smooth sigmoid-like)
    let dead = ((20.0 - pr) / 20.0).clamp(0.0, 1.0);
    score += 25.0 * dead * dead;

    // Lookahead: reward residual that can still host the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (-gap * gap / 400.0).exp() * (0.4 + 0.6 * progress);
    }

    // Last-chance bonus (smooth in fitting_bins_count)
    if fitting_bins_count <= 1 {
        score -= 15.0 * fill;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mild pressure from many open bins vs. mean residual, modulated by progress
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap).powi(2) * (1.0 - progress);

    // New-bin candidate: keep it slightly worse than a decent fit, but attractive
    // when the item leaves a very awkward residual in any open bin
    if bin_residual == bin_capacity {
        score = 35.0 - 10.0 * fit_ratio + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small, unusable" classes are rewarded (dead space is already sunk).
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= eighth {
        // Tiny leftover: bin is effectively sealed, good packing density.
        score -= 12.0;
    } else if post_residual <= quarter {
        // Moderate leftover: check if the next item can consume it exactly.
        if next_item_size > 0 && next_item_size <= post_residual {
            // Harmonic match: next item divides the leftover well.
            let rem = post_residual % next_item_size.max(1);
            if rem == 0 { score -= 20.0; } else { score -= 8.0; }
        } else {
            // Leftover too small for next item: penalize dead space creation.
            score += 15.0;
        }
    } else {
        // Large leftover: still flexible, mild reward scaled by divisibility.
        let cls = post_residual / eighth.max(1); // integer-division class 4..=7
        score -= (cls as f64) * 2.0;
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual <= quarter { score -= 10.0; }
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Slight preference for consolidating early, fresh bins late.
        score += 5.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size > quarter {
            // Big next item: a fresh bin is valuable.
            score -= 10.0;
        }
    }

    // Coupling with mean residual: prefer bins tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Mild pressure to close bins when many are open.
    score += (open_bins_count as f64) * 0.05 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // A residual that is too small to hold even the minimum item (1) is pure waste,
    // but residuals that cannot hold the *next* item are practically dead too.
    if post_residual > 0 {
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // Dead space relative to the lookahead item: heavy penalty,
                // scaled by how close the dead gap is (smaller gap = worse).
                let gap_ratio = post_residual as f64 / next_item_size as f64;
                score += 40.0 * (1.0 - gap_ratio);
            } else {
                // Gap fits the next item: reward proportional to snugness.
                let snug = 1.0 - (post_residual as f64 / next_item_size as f64);
                score -= 15.0 * snug;
            }
        }
        // Absolute tiny-gap penalty (unusable for nearly anything).
        if post_residual < 10 {
            score += 25.0 * (1.0 - post_residual as f64 / 10.0);
        }
    } else {
        // Perfect fill: strong reward.
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing
    // bins rather than spreading; penalize placements that leave large residuals
    // when the bin fleet is already large.
    let ob_pressure = open_bins_count as f64;
    score += 0.05 * ob_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make the fresh bin attractive only when the current item
    // would leave a large dead gap in every existing bin, or when residuals across
    // the fleet are already fragmented. Otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        // Baseline mild penalty so existing bins with decent fits win.
        score += 12.0;
        // Reward a new bin when open-bin count is low (early stream) or when the
        // item is large (hard to place later).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);
        // If mean residual is small (fleet is nearly full), a new bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
        // If the next item is small, a fresh bin can absorb both nicely.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Slight preference for tighter existing fits overall (lower post_residual wins ties).
    score += 0.01 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect pairing: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement; reward tight leftover.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize dead space growth.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Prefer bins whose residual is already below the mean (tight bins first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize new-bin opening unless current bin is a hopeless fit.
    if bin_residual == bin_capacity {
        // New bin: neutral base, but discourage if an open bin has small residual.
        score += 30.0 * (1.0 - (bin_residual as f64 - post_residual as f64) / bin_capacity as f64);
        if post_residual as f64 > mean_residual {
            score += 15.0;
        }
    }

    // Late-stream consolidation: push toward filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space superlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);

    // Lookahead: if the next item fits exactly into the resulting residual, reward strongly.
    if next_item_size > 0 {
        let nd = post_residual as i64 - next_item_size as i64;
        if nd == 0 {
            score -= 60.0;
        } else if nd > 0 {
            // Next item fits: mild reward proportional to tightness.
            score -= (next_item_size as f64 / bin_capacity as f64) * 20.0;
        } else {
            // Next item won't fit here: penalize leaving a big unusable gap.
            score += (-nd as f64).min(post_residual as f64) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Competition: prefer the bin among many that fits most tightly.
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 15.0;

    // Global state: if mean residual across open bins is large, discourage
    // spreading items (prefer tight bins); if small, mild new-bin tolerance.
    score += (mean_residual - post_residual as f64) * 0.2;

    // Penalize opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
        // But allow new bin early or when item is large relative to capacity.
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
    }

    // Prefer filling larger-residual bins slightly (first-fit-decreasing flavor).
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual

    // Base: prefer tight fits, with a non-linear (quartic) penalty on large leftovers
    let mut score = post * (1.0 + 0.8 * x * x);

    // Stream-progress coupling: early on, waste is cheaper; later, dead space is costly
    let urgency = progress * progress;
    score += 18.0 * urgency * x * x * x;

    // Last-chance bonus: only bin that fits -> strongly reward using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + urgency);
    }

    // Penalize bins far below mean residual (fragmentation asymmetry), smoothed
    score += 0.15 * (mean_residual - post).abs() * (1.0 + urgency);

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let compat = (x - nx).abs();
        score += 10.0 * urgency * compat * compat;
        if x >= nx {
            score -= 6.0 * urgency * nx;
        }
    }

    // Slight penalty on proliferating many open bins early
    score += 0.5 * (open_bins_count as f64).sqrt() * (1.0 - urgency);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Small leftover classes are rewarded.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / c;

    // Integer-division thresholds: residual <= 20 is "dead space" class.
    if post_residual <= bin_capacity / 5 {
        score += 40.0 * (1.0 - frac * 5.0); // penalize tiny leftovers, worse the smaller
    } else if post_residual <= bin_capacity / 2 {
        // Mid class: leftover can still host mid-size items; mild reward.
        score -= 8.0;
    } else {
        // Large leftover: excellent fit, strong reward.
        score -= 15.0 + 10.0 * frac;
    }

    // Modulo arithmetic on residual: residuals that are multiples of small
    // harmonics (e.g. divisible by 10) pair well with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is harmonically perfect.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it nests.
            let nest = (post_residual - next_item_size) as f64;
            score -= 12.0 - nest * 0.15;
        } else {
            // Next item won't fit here; slight penalty scaled by overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += (over * 0.05).min(10.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer tight fits overall: reward small post_residual relative to item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness;

    // Stream progression: early on, be more willing to open fresh bins
    // (keep flexibility); later, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus flexibility bonus early.
        score += 25.0 - 20.0 * progress;
        // Penalize new bin if many open bins are already underused.
        if mean_residual > c * 0.5 {
            score += 15.0;
        }
    } else {
        // Existing bin: reward grows with progress (consolidation pressure).
        score -= 5.0 * progress;
    }

    // Penalize opening bins when many already exist and fit is mediocre.
    if open_bins_count > 3 && post_residual < bin_capacity / 4 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Dead-space avoidance: tiny leftovers are nearly useless.
