    // Harmonic class logic on post_residual fractions.
    let frac = post_residual as f64 / cap;
    if frac >= 0.4 && frac <= 0.6 {
        score -= 12.0;
    } else if frac > 0.6 && frac <= 0.8 {
        score -= 6.0;
    } else if frac < 0.2 && post_residual > 0 {
        score += 8.0;
    }

    // Modulo harmonic pockets.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    }

    // Strong two-step lookahead: chain packing.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            let gap = post - next;
            if gap == 0.0 {
                score -= 500.0;
            } else if gap <= 10.0 {
                score -= 150.0;
            } else {
                score -= 40.0 * (1.0 - gap / post.max(1.0));
            }
            if post_residual % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            score += 0.5 * (next - post);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Consolidation pressure grows early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score += 0.2 * open_bins_count as f64 * (1.0 - progress);
    }

    // Relative-to-mean: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: penalize fresh bins when open bins have room,
    // but allow a fresh bin if the next item is huge and would strand residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = mean_residual / cap;
        score += 30.0 + 40.0 * crowding - 10.0 * (1.0 - progress) + 0.5 * item_size as f64;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
