    let norm_post = post / cap;

    // Base: prefer tight fits, scaled by smooth polynomial in post_residual
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Stream-progress coupling: later in stream, penalize waste more aggressively
    let p2 = progress * progress;
    score += progress * post * (0.3 + 0.7 * p2);

    // Dead-space avoidance: hard bonuses for perfect / near-perfect fills
