        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Harmonic class logic on post_residual fractions
    if norm_post >= 0.4 && norm_post <= 0.6 {
        score -= 12.0;
    } else if norm_post > 0.6 && norm_post <= 0.8 {
        score -= 6.0;
    } else if norm_post < 0.2 && post_residual > 0 {
        score += 8.0;
    }

    // Modulo harmonic pockets
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Strong two-step lookahead: chain packing
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let gap = post - next_item_size as f64;
        if gap == 0.0 {
            score -= 500.0;
        } else if gap <= 10.0 {
            score -= 150.0;
        } else {
            score -= 40.0 * (1.0 - gap / post.max(1.0));
        }
        if post_residual % next_item_size == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 - post) / cap;
    }

    // Crowding: many open bins with high mean residual -> encourage consolidation
