    if frac >= 0.4 && frac <= 0.6 {
        score -= 12.0 ;
    } else if frac > 0.6 && frac <= 0.8 {
        score -= 7.0 ;
    } else if frac > 0.8 {
        score -= 12.0 + 8.0 * frac ;
    }

    // Lookahead: reward leaving exactly the space the next item needs
    if next_item_size > 0 {
        let next = next_item_size as f64 ;
        if pr >= next {
            let gap = pr - next ;
            if gap == 0.0 {
                score -= 470.0 ;
