            }
            if gap > next_item_size as f64 {
                score -= 8.0 ;
            }
            // Penalize leaving a residual that is large yet too small for the next item
            if gap > 0.0 && gap < 8.0 && next > 8.0 {
                score += 25.0 ;
            }
        } else {
            score += (0.4 * (next - pr)) . min (15.0) ;
