    // Stream-progress coupling: later items penalize waste more
    score += progress * post * (0.3 + 0.7 * p2);

    // Dead-space penalty
    let dead = (1.0 - norm_post).min(1.0);
    score += 20.0 * dead * dead * (1.0 - norm_post);

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
