pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c;

    // Dead-space ladder: near-zero leftovers are almost perfect bins.
    if post_residual == 0 {
        score -= 1300.0;
    } else if post_residual <= 3 {
        score -= 250.0;
    } else if post_residual <= 5 {
        score -= 180.0;
    } else if post_residual <= 10 {
        score -= 75.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 22.0 * (1.0 - frac * 5.0);
    } else if post_residual <= bin_capacity / 2 {
        score -= 8.0;
    } else {
        score -= 15.0 + 10.0 * frac;
    }

    // Harmonic residual classes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead: exact / near nesting of the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if pr >= next {
            let gap = pr - next;
            if gap == 0.0 {
                score -= 480.0;
            } else if gap <= 10.0 {
                score -= 145.0;
            } else if gap <= 25.0 {
                score -= 48.0 * (1.0 - gap / 25.0);
            } else {
                score -= 32.0 * (1.0 - gap / pr.max(1.0));
            }
            if post_residual % next_item_size == 0 {
                score -= 16.0;
            }
            if gap >= next && (gap - next) <= 4.0 {
                score -= 30.0;
            }
        } else {
            score += (0.45 * (next - pr)).min(18.0);
            if pr < next * 0.25 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Tightness reward.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness;

    // New-bin candidate handling: keep flexibility early, resist waste later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
        if mean_residual > c * 0.5 {
            score += 15.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Penalize mediocre fits when many bins are open.
    if open_bins_count > 3 && post_residual < bin_capacity / 4 {
        score += 5.0;
    }

    // Global drift: pull toward bins whose residual is near the mean
    // (keeps residuals homogeneous, improving future pairing).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
