    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // --- Open bins pressure: with many open bins, prefer consolidation ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.9 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    // --- Last-chance bin: if this is the ONLY bin that fits, avoid opening new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are poor
        // for this item (item barely fits nowhere tightly) or late in stream
        // with many bins. Otherwise discourage.
        let worst_case = (mean_residual - item_size as f64).abs();
        score = 45.0 + 0.3 * open_bins_count as f64 - 0.2 * worst_case;
        if next_item_size > 0 && next_item_size >= item_size {
            // saving empty space for a bigger lookahead item can be smart
            score -= 10.0;
        }
        if progress > 0.7 && open_bins_count > 3 {
            score -= 5.0;
        }
    }

    score
}

