                score -= 24.0;
            }
            if gap >= next && (gap - next) <= 4.0 {
                score -= 30.0;
            }
        } else {
            // leftover too small for the lookahead item: penalize stranded gaps
            score += (0.45 * (next - pr)).min(18.0);
            if pr < next * 0.5 {
                score += 12.0;
            }
            if pr < next * 0.25 {
                score += 10.0;
            }
        }
    }

    // Only-fitting-bin: discourage opening a new bin
    if fitting_bins_count <= 1 && post_residual > 0 && post_residual < item_size {
        score -= 20.0;
    }

    // Consolidation pressure vs mean residual
    score += 0.3 * (mean_residual - bin_residual as f64);

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin only pays off when no open bin can take the item
        // well, or when saving space for a large lookahead item.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_score = 60.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            new_score -= 80.0;
        }
        if next_item_size > 0 && next_item_size > item_size && next_item_size >= bin_capacity / 2 {
            new_score -= 25.0;
        }
        if progress > 0.7 && open_bins_count > 3 {
            new_score -= 5.0;
        }
        score = new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible item (items are >= 1, but small gaps < ~10 are hard to fill)
    // get a heavy penalty. Perfect fills (post_residual == 0) are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score += 25.0; // nearly-unusable sliver
    } else if post_residual <= 10 {
        score += 12.0;
    }

    // Reward bins whose leftover can host the lookahead item exactly (k=2 lookahead)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0; // leftover still usable for next item
        } else {
            score += 6.0; // leftover cannot fit next item
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidation into
    // existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64).ln() * 3.0;
    score += pressure;

    // Last-chance bin: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are badly fragmented (mean residual small relative to item).
    if bin_residual == bin_capacity {
        score += 30.0;
        if mean_residual < item_size as f64 * 1.5 {
            score -= 20.0; // fragmentation justifies a fresh bin
        }
    }

    // Slight preference for tighter fits overall: relative fill ratio bonus.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // Mild stream-phase coupling: early on, be more conservative with new bins.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - phase) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
