                score -= 145.0;
            } else if gap <= 25.0 {
                score -= 48.0 * (1.0 - gap / 25.0);
            } else {
                score -= 32.0 * (1.0 - gap / pr.max(1.0));
            }
            if post_residual % next_item_size == 0 {
