            if gap >= next && (gap - next) <= 4.0 {
                score -= 30.0;
            }
        } else {
            score += (0.45 * (next - pr)).min(18.0);
            if pr < next * 0.5 { score += 12.0; }
            if pr < next * 0.25 { score += 10.0; }
        }
    }

    // Last-chance bin: favor using it before opening a new bin
    if fitting_bins_count == 1 && post_residual > 0 && post_residual < item_size {
