    if bin_residual == bin_capacity {
        let avg_badness = (mean_residual - 25.0).max(0.0);
        score += 18.0 - avg_badness.min(18.0);
        // early in stream, opening bins is cheaper; later, avoid fragmentation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for bins already below mean residual (consolidate space).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Integer-division threshold: bins whose residual is in a "large" harmonic band
    // (residual / 25 >= 3, i.e. >= 75) are valuable; avoid wasting them on small items.
    if bin_residual / 25 >= 3 && item_size <= 30 {
        score += 8.0;
    }

    score
}

