    if post_residual == 0 {
        score -= 1300.0; // perfect fill
    } else if post_residual <= 3 {
        score -= 250.0;
    } else if post_residual <= 5 {
        score -= 185.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 22.0 * (1.0 - norm_post * 5.0); // small dead slivers
