    // Harmonic band logic on fractional residual value.
    if norm_post >= 0.4 && norm_post <= 0.6 {
        score -= 16.0;
    } else if norm_post > 0.6 && norm_post <= 0.8 {
        score -= 7.0;
    } else if norm_post > 0.8 {
        score -= 12.0 + 8.0 * norm_post;
    }

    // Modulo classes: reusable harmonic pockets.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    }

    // Lookahead coupling with gap-tiered rewards.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            let gap = post - next;
            if gap == 0.0 {
                score -= 480.0; // perfect chain
            } else if gap <= 10.0 {
                score -= 150.0;
            } else if gap <= 25.0 {
                score -= 48.0 * (1.0 - gap / 25.0);
            } else {
                score -= 32.0 * (1.0 - gap / post.max(1.0));
            }
            if post_residual % next_item_size == 0 {
                score -= 16.0; // tiling potential
            }
            if gap > next {
                score -= 10.0;
            }
            if post >= 2.0 * next && post - 2.0 * next <= 8.0 {
                score -= 26.0; // room for two next-items
            }
            if gap <= 3.0 && post_residual <= 12 {
                score -= 30.0;
            }
        } else {
            // next item won't fit; leftover becomes dead weight
            score += (0.45 * (next - post)).min(18.0);
            if post < next * 0.5 { score += 12.0; }
            if post < next * 0.25 { score += 12.0; }
            if next - post <= 2.0 { score += 20.0; }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: open only when bins are crowded or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = if fitting_bins_count > 0 {
            1.0 / (1.0 + fitting_bins_count as f64)
        } else {
            1.0
        };
        score += 10.0 - 9.0 * progress + 0.2 * (item_size as f64)
            - 14.0 * scarcity * (1.0 - progress);
    }

    // Mild consolidation pressure across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Perfect / near-perfect fills: extremely strong rewards.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 3 {
        score -= 260.0;
    } else if post_residual <= 5 {
        score -= 180.0;
    } else if post_residual <= 10 {
        score -= 85.0;
    } else if post_residual <= bin_capacity / 5 {
        let frac = pr / c;
        score += 40.0 * (1.0 - frac * 5.0);
    } else if post_residual <= bin_capacity / 2 {
        let frac = pr / c;
        if frac >= 0.4 && frac <= 0.6 {
            score -= 16.0;
        } else {
            score -= 8.0;
        }
    } else {
        let frac = pr / c;
        score -= 15.0 + 10.0 * frac;
    }

    // Harmonic divisibility bonuses.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead: exact and near-exact nesting of the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next == pr {
            score -= 480.0;
        } else if next < pr {
            let gap = pr - next;
            if gap <= 10.0 {
                score -= 140.0;
            } else if gap <= 25.0 {
                score -= 48.0 * (1.0 - gap / 25.0);
            } else {
                score -= 12.0 + 20.0 * (1.0 - gap / pr.max(1.0));
            }
            if post_residual % next_item_size == 0 {
                score -= 16.0;
            }
            // Room for the next item twice: nearly perfect continuation.
            if pr >= 2.0 * next && pr - 2.0 * next <= 8.0 {
                score -= 26.0;
            }
        } else {
            let over = next - pr;
            score += (0.45 * over).min(18.0);
            if pr < next * 0.5 {
                score += 12.0;
            }
            if next - pr <= 2.0 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Tightness reward.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness;

    // Dead-space quadratic penalty relative to capacity.
    let norm_post = pr / c;
    score += 8.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post);

    // Stream progression: consolidation pressure grows over time.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
