        if mean_residual > c * 0.5 {
            score += 15.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mediocre fit among many open bins: penalty.
    if open_bins_count > 3 && post_residual < bin_capacity / 4 {
        score += 5.0;
    }

    score
}

