    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 45.0; // chain of perfect fits
        } else if slack < 15 {
            score -= 20.0; // next item fits with tiny waste
        } else {
            score -= slack as f64 * 0.3; // mild reward proportional to leftover usefulness
        }
