pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic dead-space class: residuals 1..=9 are nearly unusable
    // (item sizes >= 10 can never fill them) -> heavy penalty
    if post_residual >= 1 && post_residual <= 9 {
        score += 35.0;
    }

    // Capacity-fraction classes: residuals in the lower quarter of the bin
    // are risky (few item sizes fit), residuals above half are comfortable
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac <= 0.10 {
        score += 12.0;
    } else if frac > 0.10 && frac <= 0.25 {
        score += 4.0;
    } else if frac > 0.5 {
        score -= 6.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // extra harmony: next item fills the bin exactly
        if next_item_size == post_residual {
            score -= 22.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this leftover -> mild penalty
        score += 6.0;
    }

    // Last-chance bin: if this is the only open bin that fits, prefer it
    // over opening a new bin (unless the fit is terrible)
    if fitting_bins_count == 1 && bin_residual != bin_capacity && post_residual >= 10 {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin: high enough that any decent
        // fit into an existing bin wins, but adjustable
        let mut nb = 100.0 - 0.3 * item_size as f64;
        if fitting_bins_count == 0 {
            // no open bin can take the item: new bin is mandatory
            nb -= 200.0;
        } else if fitting_bins_count == 1 {
            // only one candidate fit exists; only override it if it's awful
            // (that case already carries dead-space penalties)
            nb -= 8.0;
        }
        // late in the stream, slightly prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += 10.0 * progress;
        score = nb;
    }

    // Mild tie-breaking: prefer bins below the mean residual (larger holes
    // get used first, keeping tight bins for tight items)
    if post_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space: residuals below the minimum item size
    // (1..=9 style tiny gaps) can never be filled again.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward when post_residual can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // The next item would not fit here; mild penalty unless residual is large enough
        // to be generally useful.
        if post_residual > 0 && post_residual < 20 {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless dead space penalty above dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> favor consolidation into existing bins,
    // making the new-bin candidate (residual == capacity) less attractive.
    if bin_residual == bin_capacity {
        // New bin baseline: cost of opening a bin grows with open_bins_count.
        score += 30.0 + open_bins_count as f64 * 3.0;
        // But if no existing bin fits well, new bin is fine: fitting_bins_count==0
        // means only the new-bin candidate exists; soften the penalty.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Late in the stream, avoid opening bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size < 30 {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way:
    // filling bins with above-mean residual spreads load; filling below-mean bins
    // (tight fits) is favored.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight preference for tighter fits overall.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
