            score += 0.05 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    } else {
        // Last item in stream: prioritize filling any existing bin completely.
        score -= 10.0;
    }

    // Global state coupling: when many bins are open, discourage fragmentation;
    // prefer placements that consolidate into already-open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 0.4 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual anchoring: prefer bins near the mean residual (balanced packing),
    // penalize extremes that create outlier dead space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream with few bins, opening fresh is less painful.
        score -= 5.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
