    // Lookahead: reward if next item fits the post residual, with divisibility check
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            let gap = post - next;
            if gap == 0.0 {
                score -= 450.0;
            } else if gap <= 10.0 {
                score -= 120.0;
            } else if gap <= 25.0 {
                score -= 45.0 * (1.0 - gap / 25.0);
            } else {
                score -= 30.0 * (1.0 - gap / post.max(1.0));
            }
            if post_residual % next_item_size == 0 {
                score -= 14.0;
            }
            if post >= 2.0 * next && post - 2.0 * next <= 8.0 {
                score -= 24.0;
            }
        } else {
            score += (0.4 * (next - post)).min(16.0);
            if post < next * 0.5 {
                score += 10.0;
            }
            if next - post <= 2.0 {
                score += 18.0;
            }
        }
    }

    // Crowding: many open bins with high mean residual -> encourage consolidation
    let crowd = (open_bins_count as f64) / (1.0 + mean_residual / cap);
    score += 0.5 * crowd * (0.5 + p2);

    // New-bin candidate: penalize opening new bins, with scarcity-aware relief
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count > 0 {
            1.0 / (1.0 + fitting_bins_count as f64)
        } else {
            1.0
        };
        score += 10.0 - 9.0 * progress + 0.2 * (item_size as f64)
            - 14.0 * scarcity * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
