            }
        } else {
            score += (0.45 * (next - post)).min(18.0);
            if post < next * 0.5 {
                score += 12.0;
            }
            if post < next * 0.25 {
                score += 12.0;
            }
            if next - post <= 2.0 {
                score += 20.0;
