    let crowd = (open_bins_count as f64) / (1.0 + mean_residual / cap);
    score += 0.5 * crowd * (0.5 + p2);

    // New-bin candidate: penalize opening new bins, with scarcity-aware relief
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count > 0 {
            1.0 / (1.0 + fitting_bins_count as f64)
        } else {
            1.0
        };
        score += 10.0 - 9.0 * progress + 0.2 * (item_size as f64)
            - 14.0 * scarcity * (1.0 - progress);
    }

    score
}

