                let gap = (next_item_size - post_residual) as f64;
                score += (gap / cap) * 20.0;
            }
        }
    }

    // Relative tightness vs mean residual: prefer bins tighter than average.
    let tightness = (bin_residual as f64) - mean_residual;
    score += (tightness / cap) * 10.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
