    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact match: post residual equals next item size (perfect 2-step packing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward close matches to next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack * 0.25);
    }
    // Penalize post residual too small for the next item (dead space for lookahead)
    if next_item_size > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        score += deficit * 0.6;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.3;

    // Penalize tiny unusable residuals
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no good fit exists; make it costly otherwise
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Late-stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };

    let mut score = post;

    // Strongly reward near-zero post residuals (perfect / near-perfect fits).
    if post_residual == 0 {
        score -= 1300.0;
    } else if post_residual <= 3 {
        score -= 250.0;
    } else if post_residual <= 5 {
        score -= 185.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 22.0 * (1.0 - norm_post * 5.0);
    }

    // Harmonic band rewards on normalized post-residual.
    if norm_post >= 0.4 && norm_post <= 0.6 {
        score -= 16.0;
    } else if norm_post > 0.6 && norm_post <= 0.8 {
        score -= 7.0;
    } else if norm_post > 0.8 {
        score -= 12.0 + 8.0 * norm_post;
    }

    // Modulo harmonic pockets: residuals tileable by common sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    }

    // Lookahead: reward chains where the next item fits the leftover.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            let gap = post - next;
            if gap == 0.0 {
                score -= 480.0; // perfect chain
            } else if gap <= 10.0 {
                score -= 150.0;
            } else if gap <= 25.0 {
                score -= 48.0 * (1.0 - gap / 25.0);
            } else {
                score -= 32.0 * (1.0 - gap / post.max(1.0));
            }
            if post_residual % next_item_size == 0 {
                score -= 16.0;
            }
            if gap > next {
                score -= 10.0;
            }
            // Two more next-items would tile the residual nearly exactly.
            if post >= 2.0 * next && post - 2.0 * next <= 8.0 {
                score -= 26.0;
            }
            if gap <= 3.0 && post_residual <= 12 {
                score -= 30.0;
            }
        } else {
            // Next item does not fit here: penalize wasted potential.
            score += (0.45 * (next - post)).min(18.0);
            if post < next * 0.5 { score += 12.0; }
            if post < next * 0.25 { score += 12.0; }
            if next - post <= 2.0 { score += 20.0; }
        }
    }

    // Dead-space quadratic penalty for large residuals.
    let dead = (1.0 - norm_post).min(1.0);
    score += 8.0 * dead * dead * (1.0 - norm_post);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: open only when bins are scarce of space or stream is early.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count > 0 {
            1.0 / (1.0 + fitting_bins_count as f64)
        } else {
            1.0
        };
        score += 10.0 - 9.0 * progress
            + 0.2 * (item_size as f64)
            - 14.0 * scarcity * (1.0 - progress)
            + 8.0 * (mean_residual / cap);
    }

    // Mild consolidation pressure across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

