pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it falls on capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Penalize residuals that fall into "awkward" harmonic classes.
    // Class by integer division of post_residual into 10-capacity buckets.
    let class = post_residual / 10;
    match class {
        0 => score += 8.0,          // tiny dead space (<10) is nearly unusable
        1 => score += 3.0,          // 10..19 usable only for smallest items
        2 => score -= 1.0,          // 20..29 decent
        3 => score -= 3.0,          // 30..39 good
        4 => score -= 4.0,          // 40..49 very good
        5 => score -= 3.0,          // 50..59 good
        _ => score -= 2.0,          // large residual: flexible but wasteful
    }

    // Modulo coupling: residuals matching common item-size multiples (10/20/25/50)
    // are harmonically "clean" and reward placement.
    if post_residual % 10 == 0 { score -= 2.0; }
    if post_residual % 25 == 0 { score -= 1.5; }
    if post_residual % 50 == 0 { score -= 1.0; }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 { score -= 25.0; }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 12.0; }
        else if next_item_size <= post_residual {
            // next item fits, but penalize leaving awkward leftover after that
            let after_next = post_residual - next_item_size;
            if after_next < 10 { score += 2.0; } else { score -= 2.0; }
        } else {
            // next item won't fit here: slight penalty unless this bin is nearly full
            if frac < 0.2 { score += 3.0; }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 6.0;
