    // New-bin candidate logic: an empty bin should only win when open bins are crowded
    // or the item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / cap;
        // Penalize opening new bins mildly; more when few bins open / low pressure.
        score += 4.0 + 6.0 * (1.0 - pressure) + 3.0 * (1.0 - progress);
