        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose residual will be exactly consumed by next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let two_step_residual = post_residual - next_item_size;
            // small two-step residual is good, but not as good as exact match
