            if two_step_residual < 10 {
                score -= 100.0;
            }
        } else {
            // next item cannot follow in this bin: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize leaving dead space that likely fits nothing (items >= 10 by default)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Compare residual against mean residual across open bins
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize slightly so it's chosen only when open bins fit poorly,
    // but allow it when all open bins would leave large unusable residuals
    if bin_residual == bin_capacity {
        let best_alternative_penalty = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            0.0
        };
        score += 40.0 + 0.2 * best_alternative_penalty;
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * (1.0 - progress);
    }

    // Mild preference for tighter bins among comparable options
    score += 0.1 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, especially perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space nonlinearly; tiny residuals (<10) are nearly unusable.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 25.0; // dead space penalty
        }
        // Reward exact closeness of fit relative to capacity
        let tightness = 1.0 - (pr / bin_capacity as f64);
        score -= 20.0 * tightness * tightness;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // next item cannot use the leftover -> dead end penalty
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of the
    // current bin. Penalize new bins unless the current bin's residual is large
    // and the item is a poor fit (big post_residual elsewhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and
        // how fragmented open bins already are.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).min(1.0)
        } else { 0.0 };
        // Early stream with fragmented bins: opening new bins is OK (keeps
        // flexibility); late stream: consolidate.
        score += 45.0 - 20.0 * progress + 15.0 * fragmentation;
        // A new bin is attractive when the item is large (poor fit candidates)
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Placing into an existing bin: mild reward scaled by how full it becomes.
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    // Global state: many open bins with high mean residual -> encourage packing
    // into existing bins to reduce fragmentation.
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Slight preference to place into bins whose residual is close to item size.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

