    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Tight fits rewarded strongly (post residual near zero)
    score -= 30.0 * (1.0 - norm_post).powi(3);

    // Smooth stream-progress coupling: early on, prefer tighter packing more
    let prog_term = 0.5 + 0.5 * progress;
    score *= 1.0 - 0.25 * prog_term * (1.0 - norm_post);

    // Penalize bins far below mean residual (fragmentation) smoothly
    score += 0.15 * (mean_residual - post).abs().powi(2) / cap;

    // Last-chance bin bonus (only fitting bin) — smooth reward
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_post);
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let fits = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let gap = (post - next_item_size as f64).max(0.0) / cap;
        score -= 10.0 * fits * (1.0 - gap);
        // Penalize leaving a gap that next item barely misses
        let miss = (next_item_size as f64 - post).max(0.0);
        if miss > 0.0 {
            score += 8.0 * (1.0 - miss / cap).powi(2);
        }
    }

    // Slight penalty for opening a new bin when many open bins exist
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
