pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize large waste quadratically.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of 10, or >= next typical small item) are rewarded.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if class == 0 {
        score -= 25.0; // decile-aligned leftover, easy to refill
    } else if class <= 3 {
        score += 18.0; // awkward sliver: dead space risk
    }

    // Integer-division thresholds on post_residual vs lookahead item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Can we also chain: does post_residual still hold next item well?
            let q = pr / next_item_size.max(1);
            score -= 8.0 * (q as f64).min(3.0);
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 12.0; // harmonic after hypothetical placement
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.9; // leftover can't host next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when residual waste would be severe
    // or the current bin is nearly full anyway.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 55.0 - 30.0 * progress;
        // Open new bin if placing here would strand a tiny residual.
        if post_residual > 0 && post_residual < 10 {
            score -= 5.0; // fresh bin keeps clean 100 residual
        } else {
            score += penalty;
        }
        score += open_bins_count as f64 * 0.5;
    }

    // Mean-residual coupling: prefer bins below mean residual (denser bins),
    // gently pushing toward balanced-but-tight packing.
    let dev = mean_residual - bin_residual as f64;
    score += 0.25 * dev;

    // Late-stream consolidation: fewer open bins preferred near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest conceivable item (<= 10) are pure waste; penalize hard.
    if post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 11.0);
    } else if post_residual < 25 {
        // Small gap zone: moderately wasteful unless next item fits it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0; // gap is usable by lookahead -> good
        } else {
            score += 8.0 * (1.0 - post_residual as f64 / 25.0);
        }
    }

    // Reward tight fits (low post residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Lookahead synergy: if next item exactly fills the new residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty if residual wasted.
        score += 3.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).powf(1.3) * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // already crowded; placing here keeps roomier bins available.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New empty bin candidate: only attractive when no good fit exists,
    // i.e., when it avoids creating tiny dead space in an existing bin.
    if bin_residual == bin_capacity {
        score += 55.0 + 5.0 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Strong tiered waste penalties (borrowed from best heuristic)
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 3 {
        score -= 220.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 70.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 30.0 * (1.0 - norm_post * 5.0);
    } else if post_residual <= bin_capacity / 2 {
        if norm_post >= 0.4 && norm_post <= 0.6 {
            score -= 16.0;
        } else {
            score -= 6.0;
        }
    } else {
        score -= 15.0 + 10.0 * norm_post;
    }

    // Progress coupling: penalize waste more later in the stream
    let p2 = progress * progress;
    score += progress * post * (0.3 + 0.7 * p2);

    // Lookahead: strong reward when next item fits post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == post {
            score -= 450.0;
        } else if nxt <= post {
            let gap = post - nxt;
            if gap <= 10.0 {
                score -= 120.0;
            } else if gap <= 25.0 {
                score -= 45.0 * (1.0 - gap / 25.0);
            } else {
                score -= 25.0 * (1.0 - gap / post.max(1.0));
            }
            if post_residual % next_item_size == 0 {
                score -= 14.0;
            }
            if post >= 2.0 * nxt && post - 2.0 * nxt <= 8.0 {
                score -= 24.0;
            }
        } else {
            let over = nxt - post;
            score += (0.4 * over).min(18.0);
            if post < over * 0.5 {
                score += 10.0;
            }
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Tightness bonus
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Crowding consolidation
    let crowd = (open_bins_count as f64) / (1.0 + mean_residual / cap);
    score += 0.5 * crowd * (0.5 + p2);

    // New-bin candidate: penalize unless waste is large or item is big
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
        if mean_residual > cap * 0.5 {
            score += 18.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    if open_bins_count > 3 && post_residual < bin_capacity / 4 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
