        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Post-residual dead space: unusable for the next item
        if next_item_size > post_residual {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 30.0;
    }

    // Penalize small dead space (< 10, minimum item size) more strongly
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
