        score += pr * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline; prefer it only when all
    // open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        score = 45.0 + frac * 0.0;
        // Scale with stream progress: late in the stream, be more conservative.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
        // If many bins are open, prefer reusing rather than opening more.
        score += open_bins_count as f64 * 0.5;
    }

    // Mean-residual coupling: prefer bins close to the mean residual
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // are pure waste — penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward very tight fits (item nearly fills the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If this bin can host the next item too, chaining is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for the next item: dead space risk.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones rather than spreading items.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 6.0;

    // Prefer bins below the mean residual when many bins are open
    // (balances residual distribution, keeps more bins usable).
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // New empty bin candidate: only attractive when the item is huge
    // and no tight fit exists; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let big = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 20.0 * big;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with little slack left
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item would not fit here: penalize leaving dead space that is too small for it
    else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless item is huge or current residuals are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * item_frac + 10.0 * progress;
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Prefer bins tighter than the average residual (good fits)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Penalize creating tiny unusable residual
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };

    // Strong dead-space ladder: near-zero residuals are excellent (bin nearly full).
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 3 {
        score -= 220.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 70.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 30.0 * (1.0 - frac * 5.0); // thin slivers: mild penalty
    } else if frac >= 0.4 && frac <= 0.6 {
        score -= 16.0; // half-band residuals are valuable
    } else if frac <= 0.8 {
        score -= 6.0;
    } else {
        score -= 15.0 + 10.0 * frac;
    }

    // Harmonic modulo classes on post_residual.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        else if post_residual % 5 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    }

    // Lookahead coupling with graded chain bonuses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0; // perfect chain
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 120.0;
            } else if gap <= 25.0 {
                score -= 45.0 * (1.0 - gap / 25.0);
            } else {
                score -= 25.0 * (1.0 - gap / pr.max(1.0));
            }
            if post_residual % next_item_size == 0 {
                score -= 14.0; // tiling potential
            }
            // two-item tiling leaving near-zero waste
            if pr >= 2.0 * next_item_size as f64 && pr - 2.0 * next_item_size as f64 <= 8.0 {
                score -= 24.0;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += (0.4 * over).min(18.0);
            if pr < over * 0.5 {
                score += 10.0;
            }
        }
    }

    // Tightness coupling: reward filling a crowded bin deeply.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening unless bins are crowded or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = mean_residual / cap;
        score += 25.0 - 20.0 * progress + 40.0 * crowding;
        if mean_residual > cap * 0.5 {
            score += 18.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 6.0; // big items: opening a fresh bin is more acceptable
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild consolidation pressure across many open bins.
    score += open_bins_count as f64 * 0.3;
    if open_bins_count > 3 && post_residual < bin_capacity / 4 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more strongly than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item's lower bound.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Wasted residual relative to what the next item could use.
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        } else {
            // Residual can host the next item: reward this synergy.
            let snug = (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64);
            score -= 3.0 * (1.0 - snug);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: encourage consolidating into existing bins.
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, more so as stream progresses or when alternatives exist.
        score += 10.0 + 25.0 * progress + 1.5 * (fitting_bins_count as f64);
        // Allow a new bin early or when item is huge and fits poorly anywhere.
        if item_size >= 70 && post_residual <= 30 {
            score -= 15.0;
        }
    } else {
        // Existing bin: mild bonus growing with stream progress.
        score -= 4.0 * progress;
    }

    // Prefer bins whose residual is close to mean residual (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly coupled with stream progress.
    // Early on, prefer tight fits strongly; later, waste matters less than bin count.
    let mut score = pr * (1.0 + 0.8 * (1.0 - progress) * (1.0 - progress));

    // Smooth quartic penalty for medium-size dead space (worst waste zone).
    score += 30.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Interaction: post residual vs mean residual — penalize bins far from the mean
    // (avoiding fragmentation), smoothly weighted.
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead coupling: reward residual that can hold next item, smoothly.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let tightness = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 12.0 * fits_next * tightness * (0.5 + progress);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty for spreading across many bins when item nearly fills bin.
    score += 0.05 * open_bins_count as f64 * (1.0 - item_size as f64 / cap);

    // New-bin candidate: make empty bin attractive only when item is large
    // and progress is late; otherwise discourage opening bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score += 40.0 * (1.0 - large_item) * (1.0 - 0.5 * progress);
        score -= 10.0 * large_item * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "usable" residue classes (multiples of 10) are more valuable.
    let post = post_residual;
    let class = post % 10;
    if post > 0 {
        if class == 0 {
            score -= 12.0; // perfectly divisible leftover
        } else {
            score += class as f64 * 1.5; // dead-space penalty by residue
        }
    } else {
        score -= 40.0; // perfect closure
    }

    // Harmonic coupling: can next_item_size exactly divide the post_residual?
    if next_item_size > 0 && post > 0 {
        if post % next_item_size == 0 {
            score -= 25.0; // chainable: leftover exactly consumed next
        } else if next_item_size <= post {
            let next_fit = next_item_size as f64 / post as f64;
            score -= 15.0 * next_fit;
        } else {
            score += 8.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // current item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0
            - 10.0 * (item_size as f64 / bin_capacity as f64)
            - 8.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Discourage spreading across many open bins when mean residual is low.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += (mean_residual - post as f64) * 0.05;

    // Integer-division threshold: bins whose residual // item_size == 1
    // (item fills more than half) are preferred for big items.
    if bin_residual / item_size.max(1) == 1 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never be reused are heavily penalized.
    // A gap is "dead" if smaller than the minimum plausible item (1) threshold band and
    // smaller than the lookahead item. Penalize proportionally to how close to dead it is.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // gap cannot host the next item -> likely dead space
            let deadness = 1.0 - (post_residual as f64) / (next_item_size as f64);
            score += 40.0 * deadness;
        }
        // Very small absolute gaps (< 15) are almost always unusable
        if post_residual < 15 {
            score += 30.0 * (1.0 - (post_residual as f64) / 15.0);
        }
    } else {
        // Perfect fill: strong reward
        score -= 60.0;
    }

    // Reward tight fits relative to the current item
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // encourage using existing bins; but if this bin is the last chance, reward strongly.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins are already open
        score += 12.0 + 2.5 * open_bins_count as f64;
        // but if mean residual across open bins is small, opening fresh may be fine
        score -= 0.05 * mean_residual;
    }

    // Slight preference for bins with residual close to mean (balanced packing)
    score += 0.03 * ((bin_residual as f64 - mean_residual).abs());

    // Mild lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a perfect chain -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Next item fits; residual after that decides chain quality.
            let chain_residual = post_residual - next_item_size;
            score -= 60.0 - chain_residual as f64 * 0.8;
            if chain_residual <= 10 {
                score -= 80.0;
            }
        } else {
            // Next item cannot follow here: penalize leaving dead space
            // proportional to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when good open bins exist and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 50.0;
        }
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 30.0; // fresh bin can host a chain
        }
    }

    // Mild preference to keep many small open bins consolidated.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space relative to smallest plausible future item (1..100 interface)
        let dead_penalty = (post_residual as f64).powf(1.4) / 12.0;
        score += dead_penalty;
        // If next item fits in the post-residual, big reward (chain packing)
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 18.0 + 0.25 * next_item_size as f64;
        }
        // If next item would fit only marginally (within 3), extra reward for tight chain
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Scarcity pressure: many open bins with high mean residual -> prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let scarcity = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    if bin_residual < bin_capacity {
        score -= scarcity * (0.5 + 0.5 * progress);
    }

    // Late in stream: avoid opening new bins, consolidate
    if progress > 0.7 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 8.0 * progress;
    }

    // New-bin candidate: penalize unless current bin residuals are all poor fits
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (post_residual as f64) < 0.0; // placeholder always false
        let waste_if_open = (bin_capacity as f64) - item_size as f64;
        let mut nb = 25.0 + waste_if_open * 0.6;
        if fitting_bins_count == 0 {
            nb -= 60.0; // no alternative: new bin is fine
        } else if fitting_bins_count == 1 {
            nb += 40.0; // prefer using the single fitting bin
        }
        if next_item_size > 0 && next_item_size > item_size && next_item_size <= bin_capacity {
            nb -= 10.0; // big item coming, fresh bin may help
        }
        if progress > 0.85 {
            nb += 20.0 * (progress - 0.85) / 0.15; // late stream: don't open bins
        }
        score += nb;
    }

    // Slight preference for tighter current fit among comparable options
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs().ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
