        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: open only when justified by waste/pressure
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
        if mean_residual > cap * 0.5 {
            score += 18.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Crowding: many open bins with small leftovers -> discourage fragmentation
    if open_bins_count > 3 && post_residual < bin_capacity / 4 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, mildly convex to punish dead space
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in stream => stronger penalty on leftover space (tighter packing desired)
    let progress_coupling = pr * (0.5 + 1.5 * progress * progress) * (1.0 - norm_item);
    score += progress_coupling * 0.8;

    // Reward near-perfect fits via smooth sigmoid-like term
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness;

    // Lookahead: reward if next item fits in post_residual (smooth quadratic affinity)
    if next_item_size > 0 {
        let fit_margin = (pr - next_item_size as f64) / cap;
        let affinity = 1.0 / (1.0 + (-6.0 * fit_margin).exp());
        score -= 12.0 * affinity * fit_margin.abs().min(1.0);
    } else {
        score -= 10.0 * (1.0 - norm_item); // last item: prefer tightest fit
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr * norm_pr);
    }

    // Slight penalty when bin residual deviates from mean residual (smooth)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Early stream: mildly discourage opening too many bins (smooth in open_bins_count)
    let bin_pressure = (open_bins_count as f64).ln() / (1.0 + progress);
    score += 3.0 * bin_pressure * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };

    // Exact / near-exact fits are overwhelmingly valuable.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 3 {
        score -= 220.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 70.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 30.0 * (1.0 - frac * 5.0);
    } else if post_residual <= bin_capacity / 2 {
        if frac >= 0.4 && frac <= 0.6 {
            score -= 16.0;
        } else {
            score -= 6.0;
        }
    } else {
        score -= 15.0 + 10.0 * frac;
    }

    // Round residuals are friendlier to future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead: reward residuals that chain with the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 120.0;
            } else if gap <= 25.0 {
                score -= 45.0 * (1.0 - gap / 25.0);
            } else {
                score -= 25.0 * (1.0 - gap / pr.max(1.0));
            }
            if post_residual % next_item_size == 0 {
                score -= 14.0;
            }
            if pr >= 2.0 * next_item_size as f64 && pr - 2.0 * next_item_size as f64 <= 8.0 {
                score -= 24.0;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += (0.4 * over).min(18.0);
            if pr < over * 0.5 {
                score += 10.0;
            }
        }
    }

    // Tightness of the current placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // New empty bin candidate: discourage by default; relax late in the
    // stream or when the item is large and mean residual is already high.
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
        if mean_residual > c * 0.5 {
            score += 18.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Last-chance bin: prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: consolidate when many bins are open.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 6.0;

    // Keep residual distribution balanced around the mean.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Penalize tiny useless residuals harder when many bins compete.
    if open_bins_count > 3 && post_residual < bin_capacity / 4 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets (capacity fractions)
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let class = pr % 10;
    match class {
        0 => score -= 25.0,          // exact / decade fit: perfect compartment
        1 | 2 => score -= 12.0,      // near-decade: still attractive
        3 | 4 | 5 | 6 | 7 => {},     // mid-range: neutral
        8 | 9 => score += 10.0,      // awkward sliver above a decade
        _ => {},
    }

    // Integer-division threshold: post_residual relative to half capacity
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr * 2 <= cap / 4 {
        score += 15.0; // very small dead space: poor use of a big residual
    } else if pr * 2 <= cap / 2 {
        score -= 8.0;  // post residual below quarter: good compact fill
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt <= pr {
            score -= 14.0; // chain placement possible
            // harmonic bonus if next item also lands on a decade boundary
            if (pr - nxt) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 6.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 10.0 * (mean_residual / bin_capacity as f64) - 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Prefer tighter bins among fitting ones
    score -= (bin_residual as f64 - post_residual as f64) * 0.3;
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals that are too small to be
    // useful for any future item are wasted space -> heavy penalty.
    if post_residual > 0 {
        // Dead space: gap smaller than the minimum plausible item (1..100 range,
        // but small items are rare; treat gaps < 10 as almost certainly dead).
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 25 {
            // Partially usable gap: graded penalty proportional to unusability.
            score += (25.0 - post_residual as f64) * 2.0;
        }

        // Perfect fit / near-perfect fit gets a strong reward.
        if post_residual == 0 {
            score -= 50.0;
        } else if post_residual <= 5 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement chains nicely -> reward; if the gap cannot hold the next
    // item and the gap is small, penalize further.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual < 25 {
            score += 15.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; keep items
    // consolidated by rewarding bins tighter than the mean residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).sqrt() * (1.0 + progress);
    if (post_residual as f64) > mean_residual {
        score += open_pressure * 3.0;
    } else {
        score -= open_pressure * 2.0;
    }

    // New-bin candidate handling: an empty bin should only win when all open
    // bins would leave severe dead space. Make the fresh bin mildly unattractive
    // by default so consolidation wins unless dead-space penalties dominate.
    if bin_residual == bin_capacity {
        score += 40.0 + open_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fill the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits snugly after this one (small leftover after both).
    if next_item_size > 0 && post_residual > next_item_size {
        let two_step_leftover = post_residual - next_item_size;
        score -= 25.0 / (1.0 + two_step_leftover as f64);
    }
    // Next item will NOT fit here -> leftover is likely dead space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.5 * (post_residual as f64).min(40.0);
    }

    // Reward tight fits relative to mean residual of open bins.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= (mean_residual - post_f).min(30.0) * 0.4;
    } else {
        score += (post_f - mean_residual).min(30.0) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize leaving tiny unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }
    // Zero residual is a perfect fill.
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., current residual would leave a large mismatched leftover).
    if bin_residual == bin_capacity {
        let waste_now = bin_residual - item_size;
        let poor_fit = fitting_bins_count == 0
            || (waste_now as f64) < 0.5 * mean_residual
            || (next_item_size > 0 && waste_now < next_item_size && waste_now > 0);
        if poor_fit {
            score -= 45.0;
        } else {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

