    // Global fragmentation pressure: if mean residual is low, avoid wasting
    let mean_res_gap = mean_residual - post_residual as f64;
    score += mean_res_gap * 0.3;

    // Prefer using existing bins over opening new ones when many bins are open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin only attractive if item is large and current fit is poor
        let fit_quality = item_size as f64 / bin_residual as f64;
        score += 25.0 - fit_quality * 40.0;
        // Late in the stream, discourage opening extra bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Mild preference for fuller bins
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 8.0;
    }

    // Nonlinear coupling: penalize leaving residual that matches no plausible item band
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 1.0 {
        score += 50.0; // impossible residual (shouldn't happen, safety)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
