        score += 30.0 * (1.0 - norm_post * 5.0);
    } else if norm_post >= 0.4 && norm_post <= 0.6 {
        score -= 16.0;
    } else {
        score -= 15.0 + 10.0 * norm_post;
    }

    // Progress coupling: later items penalize waste harder
    let p2 = progress * progress;
    score += progress * post * (0.3 + 0.7 * p2);

    // Dead-space penalty
    let dead = (1.0 - norm_post).min(1.0);
    score += 20.0 * dead * dead * (1.0 - norm_post);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead with exact-match and divisibility rewards
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == post {
            score -= 450.0;
        } else if nxt <= post {
            let gap = post - nxt;
            if gap <= 10.0 {
                score -= 120.0;
            } else if gap <= 25.0 {
                score -= 45.0 * (1.0 - gap / 25.0);
            } else {
                score -= 25.0 * (1.0 - gap / post.max(1.0));
            }
            if post_residual % next_item_size == 0 {
                score -= 14.0;
            }
            if post >= 2.0 * nxt && post - 2.0 * nxt <= 8.0 {
                score -= 24.0;
            }
        } else {
            let over = nxt - post;
            score += (0.4 * over).min(18.0);
            if post < over * 0.5 {
                score += 10.0;
            }
        }
    }

    // Crowding / consolidation
    let crowd = (open_bins_count as f64) / (1.0 + mean_residual / cap);
    score += 0.5 * crowd * (0.5 + p2);

    // New-bin candidate: open only when current bins are mostly full or item is big
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
        if mean_residual > cap * 0.5 {
            score += 18.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    if open_bins_count > 3 && post_residual < bin_capacity / 4 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium gaps (10..=20) are partially usable but risky.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // If the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // Penalize if next item cannot fit in post residual (forced split).
    if next_item_size > post_residual && next_item_size > 0 {
        score += next_item_size as f64 * 0.3;
    }

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Pressure from many open bins: prefer filling existing bins.
    score += open_bins_count as f64 * 1.5;

    // Deviation from mean residual: prefer bins that are fuller than average.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate: baseline high cost, reduced late in stream
    // or when item is huge and fits nowhere well.
    if bin_residual == bin_capacity {
        score = 120.0
            - (step_index as f64 / total_items.max(1) as f64) * 20.0
            - (fitting_bins_count as f64) * 5.0;
        // Opening a new bin is reasonable if item is large and would leave
        // a small dead gap in any existing bin.
        if item_size > bin_capacity * 3 / 4 && post_residual == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

