    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match strongly rewarded; near-matches partially rewarded.
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score += diff * 0.6;
        }
        // If next item can't fit here anyway, mild penalty for wasting the slot.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: minimize waste directly.
        score += post_residual as f64 * 0.5;
    }

    // Compare post_residual relative to mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer filling tighter bins (small residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 8.0;

    // Penalize creating tiny unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Slight preference for opening new bins when many bins are already open
    // and this placement would leave a large awkward residual.
    if post_residual > 50 && open_bins_count > 3 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
