    // Dead-space penalty: residuals too small for typical items
    let dead = (1.0 - norm_post).min(1.0);
    score += 20.0 * dead * dead * (1.0 - norm_post);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual (stronger for exact match)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == post {
