        } else if nxt <= post {
            let gap = post - nxt;
            if gap <= 10.0 {
                score -= 120.0;
            } else if gap <= 25.0 {
                score -= 45.0 * (1.0 - gap / 25.0);
            } else {
                score -= 25.0 * (1.0 - gap / post.max(1.0));
            }
            // divisibility bonus: residual reusable in whole chunks
            if post_residual % next_item_size == 0 {
                score -= 14.0;
            }
            // two-copies fit leaving tiny remainder
            if post >= 2.0 * nxt && post - 2.0 * nxt <= 8.0 {
                score -= 24.0;
            }
