    // Crowding: many open bins with high mean residual -> encourage consolidation
    let crowd = (open_bins_count as f64) / (1.0 + mean_residual / cap);
    score += 0.5 * crowd * (0.5 + p2);

    // New-bin candidate: penalize opening new bins unless waste is large or item is big
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
        if mean_residual > cap * 0.5 {
            score += 18.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Consolidation nudge: many bins open and this leaves a small residual
    if open_bins_count > 3 && post_residual < bin_capacity / 4 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity is valuable.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * tightness * (item_size as f64);

    // Exact or near-exact fill is excellent.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item still fits here: good, keep pairing chain alive
            score -= 8.0;
            // extra reward if next item fits almost exactly too
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 10.0;
            }
        } else {
            // post-residual becomes dead space relative to next item
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global state coupling: when mean residual is high, prefer using
    // already-loose bins rather than fragmenting further.
    score += 0.05 * mean_residual;

    // Penalize bins that deviate strongly from the mean residual
    // (encourages balanced residual distribution).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // New-bin candidate: penalize opening a fresh bin unless it is genuinely
    // beneficial (few fitting bins, or item is large and no open bin is roomy).
    if bin_residual == bin_capacity {
        let open_f64 = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a new bin grows with number of open bins.
        let mut new_bin_cost = 30.0 + 3.0 * open_f64;
        // Late in the stream, opening new bins is cheaper than fragmenting
        // (fewer future items to fill them).
        new_bin_cost *= 1.0 - 0.5 * progress;
        // If item barely fits nowhere well (only one fitting bin), new bin is bad.
        if fitting_bins_count <= 1 {
            new_bin_cost += 40.0;
        }
        // Large items (>= 60) may justify fresh space.
        if item_size >= 60 {
            new_bin_cost -= 15.0;
        }
        score += new_bin_cost;
    }

    // Slight preference for filling emptier bins when many bins are open
    // (consolidation pressure).
    score -= 0.02 * open_bins_count as f64 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fill is ideal: zero waste.
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 3 {
        score -= 220.0; // near-perfect fill
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 70.0;
    } else if post_residual <= bin_capacity / 5 {
        // small slivers: penalize proportionally to uselessness
        score += 30.0 * (1.0 - frac * 5.0);
    } else if post_residual <= bin_capacity / 2 {
        if frac >= 0.4 && frac <= 0.6 {
            score -= 16.0; // half-bin band is reusable
        } else {
            score -= 6.0;
        }
    } else {
        score -= 15.0 + 10.0 * frac;
    }

    // Harmonic pockets: residuals divisible by common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead: chain the next item into this bin's leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0; // perfect chain
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 120.0;
            } else if gap <= 25.0 {
                score -= 45.0 * (1.0 - gap / 25.0);
            } else {
                score -= 25.0 * (1.0 - gap / pr.max(1.0));
            }
            if post_residual % next_item_size == 0 {
                score -= 14.0; // tiling potential
            }
            if pr >= 2.0 * next_item_size as f64 && pr - 2.0 * next_item_size as f64 <= 8.0 {
                score -= 24.0; // two more items tile it nearly exactly
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += (0.4 * over).min(18.0);
            if pr < over * 0.5 {
                score += 10.0;
            }
        }
    }

    // Tightness coupling: reward filling a bin deeply.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // New-bin candidate gating: open a bin only when existing bins
    // are crowded or the stream is early.
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
        if mean_residual > cap * 0.5 {
            score += 18.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 6.0; // big items deserve fresh bins
        }
    } else {
        score -= 5.0 * progress;
    }

    // Last-chance bin: avoid wasting an otherwise-fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Consolidation pressure when many bins are open.
    if open_bins_count > 3 && post_residual < bin_capacity / 4 {
        score += 6.0;
    }
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = fit_norm * fit_norm * (1.0 - fit_norm);
    score -= 30.0 * poly * (1.0 + progress);

    // Tight fits strongly favored, more so early in the stream
    score -= 20.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (1.0 - 0.5 * progress);

    // Penalize near-full bins late in the stream when lookahead item can't use residue
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 8.0 * ((nx - pr) / cap) * (0.5 + progress);
        } else {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last chance bin: reward strongly
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Dead-space penalty: small post residual that is hard to reuse
    if pr < 10.0 {
        score += 5.0 * (10.0 - pr) / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

