    }

    // Integer-division harmonic classes on post_residual (mod logic).
    let class = post_residual / 10; // 0..=10 harmonic buckets
    score += match class {
        0 => 6.0,
        1 => 4.0,
        2 | 3 => 0.0,
        4 | 5 | 6 => -3.0,
        _ => -5.0,
    } as f64;

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // chain fit
        } else if next_item_size <= post_residual {
            score -= 10.0;
