    // New-bin candidate handling: opening fresh bins is only attractive early
    // in the stream or when many bins are open relative to progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin: baseline cost of one extra bin.
        score = 100.0;
        score -= 40.0 * (1.0 - progress); // cheaper to open bins early
        if open_bins_count == 0 {
            score -= 60.0; // must open first bin
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative
        }
    } else {
        // Prefer reusing bins over opening new ones, scaled by residual tightness.
        score -= 12.0;
        score += 0.05 * (mean_residual - post_f).abs();
    }

    score
}

