    // Open-bin pressure: with many open bins, discourage opening new ones.
    let open_pressure = open_bins_count as f64 * 1.5;
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += is_new_bin * open_pressure;

    // Lookahead: favor bins whose leftover could still fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Slight preference for tighter bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Late-stream consolidation: prefer existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += is_new_bin * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item size are worthless.
    if post_residual < 10 {
        score += 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect chain), scaled by lookahead size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-item packing of this bin
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + tight / 10.0);
        } else {
            // Next item cannot follow: penalize, worse the more space is wasted
            let waste = (next_item_size - post_residual) as f64;
            score += 12.0 * (waste / 100.0);
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean
    // (fill the fuller bins first, keep slack bins flexible).
    let rel = post_residual as f64 - mean_residual;
    score += 0.30 * rel;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize it, but relax the penalty late in
    // the stream or when many bins are open (diversification).
    if bin_residual == bin_capacity {
        let mut penalty = 55.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty -= 15.0 * progress;
        penalty -= (open_bins_count as f64).min(10.0);
        score += penalty;
    }

    // Tightness reward: near-exact fits are always good.
    if post_residual as f64 <= 0.05 * bin_capacity as f64 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let frac = pr / cap;

    // Base: post residual as waste
    let mut score = pr;

    // Tiered tight-fit rewards (strong bonus for near-perfect fits)
    if post_residual == 0 {
        score -= 1200.0;
    } else if post_residual <= 3 {
        score -= 220.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 70.0;
    } else if post_residual <= bin_capacity / 5 {
        score += 30.0 * (1.0 - frac * 5.0);
    } else if post_residual <= bin_capacity / 2 {
        if frac >= 0.4 && frac <= 0.6 {
            score -= 16.0;
        } else {
            score -= 6.0;
        }
    } else {
        score -= 15.0 + 10.0 * frac;
    }

    // Divisibility hints
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead with next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 120.0;
            } else if gap <= 25.0 {
                score -= 45.0 * (1.0 - gap / 25.0);
            } else {
                score -= 25.0 * (1.0 - gap / pr.max(1.0));
            }
            if post_residual % next_item_size == 0 {
                score -= 14.0;
            }
            if pr >= 2.0 * next_item_size as f64 && pr - 2.0 * next_item_size as f64 <= 8.0 {
                score -= 24.0;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += (0.4 * over).min(18.0);
            if pr < over * 0.5 {
                score += 10.0;
            }
        }
    }

    // Tightness of current placement
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Only-fitting-bin bonus (parent idea, retained)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
        if mean_residual > cap * 0.5 {
            score += 18.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Consolidation pressure when many bins open with small post residuals
    if open_bins_count > 3 && post_residual < bin_capacity / 4 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Dead-space penalty for small awkward leftovers (hard to reuse).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when fits are poor
    // or the current item would leave an unusable remainder.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5;
        let awkward = post_residual > 0 && post_residual < 10;
        if poor_fit || awkward {
            score -= 60.0;
        } else {
            score += 35.0;
        }
    }

    // Lookahead: if the next item would fit the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0;
            // Bonus when next item fits snugly too (chain of good fits).
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * next_fit;
        } else {
            // Next item won't fit here: mildly penalize wasting large residuals
            // that could have served the next item.
            if next_item_size as f64 > post_residual as f64
                && next_item_size as f64 <= bin_residual as f64
            {
                score += 6.0;
            }
        }
    }

    // Global state coupling: many open bins with high mean residual suggests
    // fragmentation; prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fragmentation = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * fragmentation * (1.0 - progress);
    }

    // Scale of open bins: with many open bins, discourage opening more.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let progress = step_index as f64 / total_items as f64;

    // Core non-linear waste penalty: convex in post residual
    let mut score = x * x * cap + 0.5 * pr;

    // Smooth coupling with stream progress: late in stream, tighten fits more
    score += 8.0 * progress * x * x * cap;

    // Reward tight fits (small post residual) with a smooth bonus
    score -= 6.0 * (1.0 - x) * (1.0 - x) * (1.0 - x) * cap * 0.05;

    // Coupling with mean residual: prefer bins deviating from mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let nx = next_item_size as f64 / cap;
        score -= 5.0 * nx * (1.0 - x);
    } else if next_item_size > 0 {
        // penalize leaving residual that next item cannot use
        score += 3.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    // New empty bin candidate: penalize opening a new bin, more so early
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    // Mild pressure to prefer filling existing bins when many are open
    score += 0.02 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions (1/8 bins)
    let cap_frac = bin_capacity as f64 / 8.0;
    let class = (post_residual as f64 / cap_frac).floor() as f64; // 0..8
    // Reward landing exactly on harmonic boundaries (perfect packing classes)
    score -= 12.0 * (class as i64 as f64 * cap_frac - post_residual as f64).abs().recip().min(1.0);

    // Penalize residual classes that are hard to fill: tiny slivers (class 0..1)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Sweet spot: residual in [10, 30] is reusable by typical small items
    if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0;
    }

    // Integer-division coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fit: strong reward, scaled by how snugly next item fits
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * snug;
        } else {
            score += 6.0; // next item won't fit here; deprioritize slightly
        }
    }

    // Last-chance bin logic
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 25.0 };
        score = 30.0 + 20.0 * progress - bad_fit + (open_bins_count as f64).sqrt() * 4.0;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's a good filler
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no future item (min size 1..100
    // but practically >= 10 historically) can use are wasted. Penalize residuals
    // in the "dead zone" (1..=12) heavily.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (1.0 - post_residual as f64 / 12.0);
    }

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect-fit bonus relative to the bin's own residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading out. Penalize candidates mildly per open bin,
    // but exempt the new-bin candidate from this (it is evaluated separately and
    // must win only when fits are genuinely bad).
    if bin_residual < bin_capacity {
        score += open_bins_count as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward this
    // placement strongly (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 20.0;
        }
        // If post_residual cannot fit the next item but could have, penalize.
        if post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size / 2 {
            score += 8.0;
        }
    }

    // Mean residual coupling: if this bin's post residual is far below the mean,
    // it is a tight fit relative to the fleet; slight reward.
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate calibration: an empty bin has huge residual; add a fixed
    // opening cost so it only wins when open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
