    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
