    }

    // Time horizon: late in the stream, be more conservative, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin: penalize more when many bins are open or late in stream,
        // but less when item is large and no open bin fits well.
        let avg_fit_gap = (bin_residual - item_size.min(bin_residual)) as f64;
        let mut new_bin_penalty = 30.0 + 25.0 * progress + 1.5 * open_bins_count as f64;
        // Encourage new bin when item is large relative to mean residual (poor fits elsewhere).
        if item_size as f64 > mean_residual {
            new_bin_penalty -= 10.0 + 0.2 * (item_size as f64 - mean_residual);
