        // If the next item is huge and this item is small, a fresh bin keeps flexibility.
        if next_item_size >= 60 && item_size <= 30 {
            new_bin_penalty -= 8.0;
        }
        score += new_bin_penalty.max(0.0);
        let _ = avg_fit_gap;
    } else {
        // Slight reward for using existing bins when many are open.
        score -= 0.3 * open_bins_count as f64;
    }

    // Coupling with global mean residual: prefer bins below mean residual (tighter bins).
    score -= 0.4 * (mean_residual - bin_residual as f64);

    score
}

