    // Reward filling bins that leave little room, scaled by how full the stream is
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * (1.0 - norm_post) * (0.3 + 0.7 * progress);

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Prefer bins whose residual is below the mean (compactness), smooth sigmoid-ish weight
    let diff = (mean_residual - bin_residual as f64) / cap;
    score += 8.0 * diff / (1.0 + (-2.0 * diff).exp());

    // Lookahead: if next item fits exactly in post_residual, reward; if post_residual
    // is too small for the next item, mild penalty (dead space for the future).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - (post - nxt) / cap).max(0.0);
        } else {
            score += 6.0 * (1.0 - nxt / cap);
        }
    }

    // Mild preference to keep number of open bins from exploding late in stream
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 defines "usable" classes.
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty: residuals in awkward classes are less likely to be
    // fillable by future small items, so penalize them more.
    let dead_penalty = match class {
        0 => 0.0,          // perfectly harmonic residual
        1 | 2 | 3 => 4.0,  // small crumbs, likely dead space
        8 | 9 => 1.0,      // nearly full bin, good compaction
        _ => 2.0,
    };
    score += dead_penalty;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (pr as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Integer-division thresholds: bin "levels" of size 25.
    let level_before = bin_residual / 25;
    let level_after = pr / 25;
    if level_after < level_before {
        // Dropping a level means good use of the bin's coarse capacity.
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits into post_residual harmonically,
    // reward strongly (chained placement).
    if next_item_size > 0 {
        if next_item_size <= pr {
            let chain_class = (pr % 10) >= (next_item_size % 10);
            score -= if chain_class { 10.0 } else { 6.0 };
        } else {
            // Next item won't fit here; this bin becomes dead unless residual
            // is in a reusable class. Penalize large unusable leftovers.
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // (high mean residual spread / item is large relative to mean).
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 {
            // Item larger than typical residual: fresh bin is reasonable.
            score -= 8.0 + mean_gap.abs() * 0.2;
        } else {
            // Open bins can likely absorb it: discourage new bin.
            score += 10.0 + mean_gap * 0.3;
        }
        // Early in stream, prefer consolidating into few bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Mild pressure toward bins with below-average residual (compact bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Late-stream consolidation: fewer open bins preferred.
    score += open_bins_count as f64 * 0.01;

    score
}
